/**
 * Show or hide the lot/serial lines of shipment and reception cards.
 * HTML is generated by getBatchLinesToggleHeader(), getBatchLineToggleLink() and getBatchLineChildRowAttributes() of core/lib/product.lib.php
 * Extrafields rows printed just after a lot line follow its visibility.
 */
$(function () {
	const withExtrafieldsRows = function (rows) {
		return rows.add(rows.nextUntil(':not(.trextrafields)').not('.hideobject'));
	};

	const setToggleIcon = function (links, visible) {
		links.find('.batchlines_icon_collapsed').toggleClass('hideobject', visible);
		links.find('.batchlines_icon_expanded').toggleClass('hideobject', !visible);
	};

	const syncHeader = function () {
		const oneGroupVisible = $('tr[data-batchgroup]:visible').length > 0;
		$('#batchlines_show_all').toggleClass('hideobject', oneGroupVisible);
		$('#batchlines_hide_all').toggleClass('hideobject', !oneGroupVisible);
	};

	const setAllGroups = function (visible) {
		withExtrafieldsRows($('tr[data-batchgroup]')).toggle(visible);
		setToggleIcon($('.batchlines_toggle'), visible);
		syncHeader();
	};

	withExtrafieldsRows($('tr[data-batchgroup]:hidden')).hide();

	$(document).on('click', '.batchlines_toggle', function () {
		const group = String($(this).data('batchtoggle'));
		const rows = $('tr[data-batchgroup]').filter(function () {
			return String($(this).data('batchgroup')) === group;
		});
		const visible = rows.first().is(':visible');

		withExtrafieldsRows(rows).toggle(!visible);
		setToggleIcon($(this), !visible);
		syncHeader();

		return false;
	});

	$('#batchlines_show_all').on('click', function () {
		setAllGroups(true);
		return false;
	});

	$('#batchlines_hide_all').on('click', function () {
		setAllGroups(false);
		return false;
	});
});
